function toolScreen(){if(selectedTool.id==='editpdf'||selectedTool.id==='organize'||selectedTool.id==='forms'){pdfEditor();return;}const t=selectedTool;content.innerHTML='<div class="v-row" style="margin-bottom:15px">'+btn(ic('arrow-left')+' '+({video:'Video tools',image:'Image tools',audio:'Audio tools',pdf:'PDF tools'}[t.group]||'Tools'),'back-tools','quiet')+'<span class="v-pill">Local processing</span></div>'+header(t.name,t.desc)+'<div class="v-two"><div><div class="v-upload" id="v-drop">'+ic('upload')+'<h3>Add your files</h3><p class="v-small v-muted">Files stay on this device.</p><div class="v-row" style="justify-content:center">'+btn('Choose files','choose-files')+'</div><input id="v-files" type="file" multiple hidden></div><div id="v-filelist"></div><div id="v-result"></div></div><aside class="v-card v-fields"><h3>Output settings</h3>'+formats()+'<div style="margin-top:20px">'+btn(t.id==='merge'?'Merge PDFs':'Process files','run-tool','primary v-full')+'</div><p class="v-small v-muted" style="margin-top:12px">Processing runs locally. Choose an output folder.</p><button class="v-button v-full" data-flow="save-task">Save these settings as a preset</button></aside></div>';const accept=t.group==='audio'?'audio/*':t.group==='video'?'video/*':t.group==='image'||['jpgpdf','scan'].includes(t.id)?'image/*':({wordpdf:'.doc,.docx',pptpdf:'.ppt,.pptx',excelpdf:'.xls,.xlsx',htmlpdf:'.html,.htm'}[t.id]||'.pdf');q('#v-files').accept=accept;q('#v-files').onchange=e=>addFiles([...e.target.files]);q('#v-drop').ondragover=e=>{e.preventDefault();q('#v-drop').classList.add('dragging');};q('#v-drop').ondragleave=()=>q('#v-drop').classList.remove('dragging');q('#v-drop').ondrop=e=>{e.preventDefault();q('#v-drop').classList.remove('dragging');addFiles([...e.dataTransfer.files]);};content.querySelectorAll('input[type=range]').forEach(r=>r.oninput=()=>{q('#'+r.id+'-value').textContent=r.value+r.dataset.unit;});renderFiles();}
function addFiles(list){window.nativeToolImport(list).then(assets=>{files.push(...assets);renderFiles();}).catch(e=>notify(e.message));}function renderFiles(){queueMicrotask(()=>window.nativeToolPreview?.(selectedTool,files));const box=q('#v-filelist');if(!box)return;const first=files[0],start=q('#v-start'),end=q('#v-end');if(first&&start&&end&&end.dataset.asset!==first.id){start.value=0;end.value=Number(first.duration.toFixed(3));start.max=end.max=first.duration;end.dataset.asset=first.id;}box.innerHTML=files.map((f,i)=>'<div class="v-rowitem">'+ic(selectedTool.group==='image'?'image':'file')+'<div class="v-grow"><strong>'+esc(f.name)+'</strong><span class="v-small v-muted">'+size(f.size)+'</span></div><div class="v-row"><button class="v-button" data-file-up="'+i+'" aria-label="Move '+esc(f.name)+' up" '+(!i?'disabled':'')+'>↑</button><button class="v-button" data-file-remove="'+i+'" aria-label="Remove '+esc(f.name)+'">×</button></div></div>').join('');icons();}
function runTool(){window.nativeTool(selectedTool,files);}
