function legacyRecorder(){content.innerHTML=header('Show it. Explain it. Done.','Record a walkthrough, then make it yours in the editor.')+'<div class="v-banner">Recording simulation · this prototype does not capture your screen, microphone or camera.</div><div class="v-two"><div><div class="v-tabs">'+['Entire screen','Window','Region'].map(n=>'<button class="v-button '+(recSource===n?'selected':'')+'" data-source="'+n+'">'+n+'</button>').join('')+'</div><div class="v-monitor"><div class="v-screen-window"><strong>'+recSource+'</strong><div></div><div style="width:70%"></div><div style="width:85%"></div></div></div><div class="v-record-clock" id="v-rec-clock">'+clock(recSeconds)+'</div><p class="v-small v-muted" style="text-align:center" id="v-rec-state">'+(recState==='idle'?'Ready when you are':recState==='recording'?'Recording demo in progress':'Recording demo paused')+'</p><div class="v-row" style="justify-content:center">'+(recState==='idle'?btn(ic('circle')+' Start recording demo','rec-start','primary'):btn(recState==='paused'?'Resume':'Pause','rec-pause')+btn('Stop & open editor','rec-stop','primary'))+'</div></div><aside class="v-card v-fields"><h3>Recording setup</h3>'+field('Microphone',select('v-mic',['Built-in microphone','Off']))+'<label class="v-check">System audio<input type="checkbox" checked></label><label class="v-check">Camera overlay<input type="checkbox"></label><label class="v-check">Capture cursor & clicks<input type="checkbox" checked></label>'+field('Quality',select('v-rec-quality',['1080p · Recommended','4K · When available']))+'<p class="v-small v-muted">The working app will ask for recording permissions and let you choose actual devices.</p></aside></div>';}
function clock(n){return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');}function startRec(){recState='recording';recorder();recTimer=setInterval(()=>{recSeconds++;if(q('#v-rec-clock'))q('#v-rec-clock').textContent=clock(recSeconds);},1000);icons();}function legacySettings(){content.innerHTML=header('Keep it comfortable.','Simple defaults for everyday laptops.')+'<div class="v-two"><div class="v-card v-fields"><h3>Performance</h3>'+field('Preview quality',select('v-previewquality',['Automatic','720p · Lighter preview','1080p · Sharper preview']))+'<p class="v-small v-muted">In the working app, lightweight previews will be separate from full-quality exports.</p><label class="v-check">Prefer local AI processing<input type="checkbox" id="v-localai" '+(s.settings.local?'checked':'')+'></label><p class="v-small v-muted">Prototype preference only. No AI models or cloud services are connected.</p>'+btn('Save preferences','settings-save','primary')+'</div><div class="v-notes"><strong>Everything together for review</strong><p>Editor, recording and every tool section are included in this prototype.</p><p class="v-small v-muted">Real processing will be integrated in stages behind the same interface, then tested together before release.</p></div></div>';q('#v-previewquality').value=s.settings.preview;}
