// 0.15: what is saved for a project: the edit without view settings (tab, track view, selection).
function editorDataV15(){const e=E();return e?.saveData?e.saveData():e?.get();}
// 0.15: edits are saved 400 ms after the last change instead of on every keystroke. flushSaveV15() saves
// at once; the main process calls it before the window closes.
let saveTimerV15=0;
function autosaveSoonV15(){clearTimeout(saveTimerV15);saveTimerV15=setTimeout(()=>{saveTimerV15=0;autosave();},400);}
