function saveFailedV15(e){const m=e?.message||String(e);notify('Not saved: '+m);if(m===saveProblemV15)return;saveProblemV15=m;if(/paused/i.test(m))return;modal('Your changes are not being saved','<p>'+esc(m)+'</p><p class="v-muted">Keep Video Visor open. After you fix this, the next change saves everything.</p>'+btn('Show projects','go-projects','primary')+btn('OK','close','quiet'));}
