function applySuggestions(){const ids=[...root.querySelectorAll('[data-suggestion]:checked')].filter(x=>!x.disabled).map(x=>x.dataset.suggestion);if(!ids.length){notify('Select at least one suggestion.');return;}const e=E().get();const changes={accepted:[...new Set([...(e.accepted||[]),...ids])],magicBefore:e.magicBefore||{audio:e.audio,colour:e.colour||false,captions:e.captions,zoom:e.zoom}};if(ids.includes('noise')||ids.includes('level'))changes.audio={...e.audio,noise:ids.includes('noise')||e.audio.noise,level:ids.includes('level')||e.audio.level};for(const key of ['colour','captions','zoom'])if(ids.includes(key))changes[key]=true;E().patch(changes);if(ids.includes('pause'))E().removeSource(14,17);if(ids.includes('repeat'))E().removeSource(25,28);closeModal();notify('Selected suggestions applied. Reopen Magic Edit to restore individual changes.');}
